import React, { useEffect, useRef, useState } from 'react';

function SongDetailWindow({ song, onClose, onNext, onPrev }) {
  const audioRef = useRef(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [volume, setVolume] = useState(1);

  useEffect(() => {
    if (isPlaying) {
      audioRef.current.play();
    } else {
      audioRef.current.pause();
    }
  }, [isPlaying, song]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
    }
  }, [volume]);

  const togglePlay = () => {
    setIsPlaying(!isPlaying);
  };

  const handleVolumeChange = (e) => {
    setVolume(parseFloat(e.target.value));
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <img src={song.cover} alt={song.album} className="detail-cover" />
        <div className="detail-info">
          <h2>{song.title}</h2>
          <h3>{song.artist}</h3>
          <p>Album: {song.album}</p>
          <p>Duration: {song.duration}</p>
        </div>
        <audio ref={audioRef} src={song.audioSrc} />
        <div className="detail-controls">
          <button onClick={onPrev} aria-label="Previous">&#9664;&#9664;</button>
          <button onClick={togglePlay} aria-label={isPlaying ? 'Pause' : 'Play'}>
            {isPlaying ? '❚❚' : '▶'}
          </button>
          <button onClick={onNext} aria-label="Next">&#9654;&#9654;</button>
          <input
            type="range"
            min="0"
            max="1"
            step="0.01"
            value={volume}
            onChange={handleVolumeChange}
            className="volume-control"
            aria-label="Volume"
          />
        </div>
        <button className="close-btn" onClick={onClose} aria-label="Close">×</button>
      </div>
    </div>
  );
}

export default SongDetailWindow;
